-- =====================================================================
-- NEXORA - Smart Attendance System Using QR Code with Anti-Proxy Verification
-- MySQL 8.x schema (InnoDB, utf8mb4)
--
-- This file does NOT create or select a database on purpose, so the same
-- file can build both the real database (nexora) and the test database
-- (nexora_test). The init script (scripts/init_db.py, Phase 2) creates
-- the database first and then runs this file inside it.
--
-- All DATETIME values are stored in UTC and are generated by the SERVER
-- (never trusted from the browser).
-- CHECK constraints are enforced by MySQL 8.0.16 and later.
-- =====================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
-- 1. ACADEMIC STRUCTURE
-- ---------------------------------------------------------------------

CREATE TABLE departments (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    code        VARCHAR(10)  NOT NULL,
    name        VARCHAR(120) NOT NULL,
    created_at  DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_departments_code (code),
    UNIQUE KEY uq_departments_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE academic_years (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    label       VARCHAR(20)  NOT NULL,              -- e.g. '2026-27'
    start_date  DATE         NOT NULL,
    end_date    DATE         NOT NULL,
    is_current  TINYINT(1)   NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_academic_years_label (label),
    CONSTRAINT ck_academic_years_dates CHECK (end_date > start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE semesters (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    academic_year_id INT UNSIGNED NOT NULL,
    semester_number  TINYINT UNSIGNED NOT NULL,     -- 1..8
    name             VARCHAR(40)  NOT NULL,
    start_date       DATE         NOT NULL,
    end_date         DATE         NOT NULL,
    is_current       TINYINT(1)   NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    UNIQUE KEY uq_semesters_year_number (academic_year_id, semester_number),
    CONSTRAINT fk_semesters_year FOREIGN KEY (academic_year_id)
        REFERENCES academic_years (id) ON DELETE RESTRICT,
    CONSTRAINT ck_semesters_number CHECK (semester_number BETWEEN 1 AND 8),
    CONSTRAINT ck_semesters_dates CHECK (end_date > start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 2. USERS AND PROFILES
-- ---------------------------------------------------------------------

CREATE TABLE users (
    id                 INT UNSIGNED NOT NULL AUTO_INCREMENT,
    email              VARCHAR(190) NOT NULL,
    password_hash      VARCHAR(255) NOT NULL,       -- Werkzeug hash, never plaintext
    full_name          VARCHAR(120) NOT NULL,
    role               ENUM('student','teacher','admin') NOT NULL,
    -- Self-registered student/teacher accounts start as 'pending' and
    -- cannot log in until an administrator approves them.
    status             ENUM('pending','active','suspended','rejected')
                       NOT NULL DEFAULT 'pending',
    approved_by        INT UNSIGNED NULL,
    approved_at        DATETIME     NULL,
    last_login_at      DATETIME     NULL,
    created_at         DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    updated_at         DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),  -- set by the app on update
    PRIMARY KEY (id),
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_role_status (role, status),
    CONSTRAINT fk_users_approved_by FOREIGN KEY (approved_by)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE classes (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    department_id    INT UNSIGNED NOT NULL,
    academic_year_id INT UNSIGNED NOT NULL,
    name             VARCHAR(60)  NOT NULL,         -- e.g. 'SE AI&DS'
    section          VARCHAR(10)  NOT NULL DEFAULT 'A',
    PRIMARY KEY (id),
    UNIQUE KEY uq_classes_identity (department_id, academic_year_id, name, section),
    CONSTRAINT fk_classes_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE RESTRICT,
    CONSTRAINT fk_classes_year FOREIGN KEY (academic_year_id)
        REFERENCES academic_years (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE student_profiles (
    user_id             INT UNSIGNED NOT NULL,
    roll_number         VARCHAR(30)  NOT NULL,
    department_id       INT UNSIGNED NOT NULL,
    class_id            INT UNSIGNED NULL,
    current_semester_id INT UNSIGNED NULL,
    admission_year      SMALLINT UNSIGNED NULL,
    phone               VARCHAR(20)  NULL,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_student_roll (roll_number),
    KEY idx_student_class (class_id),
    CONSTRAINT fk_student_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_student_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE RESTRICT,
    CONSTRAINT fk_student_class FOREIGN KEY (class_id)
        REFERENCES classes (id) ON DELETE SET NULL,
    CONSTRAINT fk_student_semester FOREIGN KEY (current_semester_id)
        REFERENCES semesters (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE teacher_profiles (
    user_id        INT UNSIGNED NOT NULL,
    employee_code  VARCHAR(30)  NOT NULL,
    department_id  INT UNSIGNED NOT NULL,
    designation    VARCHAR(80)  NULL,
    phone          VARCHAR(20)  NULL,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_teacher_employee (employee_code),
    CONSTRAINT fk_teacher_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_teacher_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 3. SUBJECTS, ENROLMENT, TEACHING ASSIGNMENTS
-- ---------------------------------------------------------------------

CREATE TABLE subjects (
    id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
    code            VARCHAR(20)  NOT NULL,
    name            VARCHAR(150) NOT NULL,
    department_id   INT UNSIGNED NOT NULL,
    semester_number TINYINT UNSIGNED NOT NULL,      -- syllabus position, 1..8
    credits         DECIMAL(3,1) NOT NULL,
    is_active       TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (id),
    UNIQUE KEY uq_subjects_code (code),
    KEY idx_subjects_dept_sem (department_id, semester_number),
    CONSTRAINT fk_subjects_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE RESTRICT,
    CONSTRAINT ck_subjects_credits CHECK (credits >= 0 AND credits <= 30),
    CONSTRAINT ck_subjects_sem CHECK (semester_number BETWEEN 1 AND 8)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- A student is enrolled in a subject for a given semester and class.
CREATE TABLE enrollments (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    student_id  INT UNSIGNED NOT NULL,
    subject_id  INT UNSIGNED NOT NULL,
    class_id    INT UNSIGNED NOT NULL,
    semester_id INT UNSIGNED NOT NULL,
    status      ENUM('active','dropped') NOT NULL DEFAULT 'active',
    enrolled_at DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_enrollment (student_id, subject_id, semester_id),
    KEY idx_enrollment_lookup (subject_id, class_id, semester_id, status),
    CONSTRAINT fk_enroll_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_enroll_subject FOREIGN KEY (subject_id)
        REFERENCES subjects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_enroll_class FOREIGN KEY (class_id)
        REFERENCES classes (id) ON DELETE RESTRICT,
    CONSTRAINT fk_enroll_semester FOREIGN KEY (semester_id)
        REFERENCES semesters (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Which teacher teaches which subject to which class in which semester.
-- Attendance sessions reference this row, so a teacher can only start a
-- session for an assignment that exists here.
CREATE TABLE teacher_subjects (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    teacher_id  INT UNSIGNED NOT NULL,
    subject_id  INT UNSIGNED NOT NULL,
    class_id    INT UNSIGNED NOT NULL,
    semester_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_teacher_assignment (teacher_id, subject_id, class_id, semester_id),
    CONSTRAINT fk_ts_teacher FOREIGN KEY (teacher_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_ts_subject FOREIGN KEY (subject_id)
        REFERENCES subjects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_ts_class FOREIGN KEY (class_id)
        REFERENCES classes (id) ON DELETE RESTRICT,
    CONSTRAINT fk_ts_semester FOREIGN KEY (semester_id)
        REFERENCES semesters (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE classrooms (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name             VARCHAR(60)  NOT NULL,
    building         VARCHAR(80)  NULL,
    latitude         DECIMAL(9,6) NOT NULL,
    longitude        DECIMAL(9,6) NOT NULL,
    default_radius_m INT UNSIGNED NOT NULL DEFAULT 50,
    PRIMARY KEY (id),
    UNIQUE KEY uq_classrooms_name (name),
    CONSTRAINT ck_classrooms_lat CHECK (latitude BETWEEN -90 AND 90),
    CONSTRAINT ck_classrooms_lng CHECK (longitude BETWEEN -180 AND 180),
    CONSTRAINT ck_classrooms_radius CHECK (default_radius_m BETWEEN 5 AND 5000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 4. DEVICE REGISTRATION AND COOLDOWN
-- A "device" is a random identifier kept in the browser. Only its SHA-256
-- hash is stored. It can be deleted or copied by a determined user, so it
-- is a deterrent, not proof of physical device identity.
-- ---------------------------------------------------------------------

CREATE TABLE device_registrations (
    id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
    device_hash     CHAR(64)     NOT NULL,
    active_user_id  INT UNSIGNED NULL,              -- user currently logged in here
    last_user_id    INT UNSIGNED NULL,              -- last user who used it
    cooldown_until  DATETIME     NULL,              -- set on logout / account switch
    first_seen_at   DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    last_seen_at    DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_device_hash (device_hash),
    CONSTRAINT fk_device_active_user FOREIGN KEY (active_user_id)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_device_last_user FOREIGN KEY (last_user_id)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE device_events (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    device_id   INT UNSIGNED NOT NULL,
    user_id     INT UNSIGNED NULL,
    event_type  ENUM('register','login','logout','account_switch',
                     'cooldown_started','cooldown_blocked') NOT NULL,
    ip_address  VARCHAR(45)  NULL,
    details     VARCHAR(255) NULL,
    created_at  DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_device_events_device (device_id, created_at),
    KEY idx_device_events_user (user_id, created_at),
    CONSTRAINT fk_devevent_device FOREIGN KEY (device_id)
        REFERENCES device_registrations (id) ON DELETE CASCADE,
    CONSTRAINT fk_devevent_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 5. ATTENDANCE
-- ---------------------------------------------------------------------

CREATE TABLE attendance_sessions (
    id                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
    assignment_id       INT UNSIGNED NOT NULL,      -- teacher_subjects row
    classroom_id        INT UNSIGNED NULL,
    status              ENUM('active','closed') NOT NULL DEFAULT 'active',
    started_at          DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    session_ends_at     DATETIME     NOT NULL,      -- configurable session duration
    closed_at           DATETIME     NULL,
    qr_validity_seconds INT UNSIGNED NOT NULL DEFAULT 120,
    -- Geofence SNAPSHOT: copied when the session starts so later edits to
    -- a classroom never silently change an existing session.
    geofence_enabled    TINYINT(1)   NOT NULL DEFAULT 1,
    geo_latitude        DECIMAL(9,6) NULL,
    geo_longitude       DECIMAL(9,6) NULL,
    geo_radius_m        INT UNSIGNED NULL,
    geo_min_accuracy_m  INT UNSIGNED NULL,
    PRIMARY KEY (id),
    KEY idx_sessions_assignment (assignment_id, status),
    KEY idx_sessions_status_end (status, session_ends_at),
    CONSTRAINT fk_sessions_assignment FOREIGN KEY (assignment_id)
        REFERENCES teacher_subjects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_sessions_classroom FOREIGN KEY (classroom_id)
        REFERENCES classrooms (id) ON DELETE SET NULL,
    CONSTRAINT ck_sessions_qr_validity CHECK (qr_validity_seconds BETWEEN 10 AND 3600),
    CONSTRAINT ck_sessions_geo CHECK (
        geofence_enabled = 0 OR (
            geo_latitude  IS NOT NULL AND geo_longitude IS NOT NULL AND
            geo_radius_m  IS NOT NULL AND geo_min_accuracy_m IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- QR tokens are random and single-purpose. Only the SHA-256 hash is
-- stored; the QR payload contains the raw token and nothing else.
-- Expiry is checked against expires_at using the database clock.
CREATE TABLE attendance_qr_tokens (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    session_id  INT UNSIGNED NOT NULL,
    token_hash  CHAR(64)     NOT NULL,
    issued_at   DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    expires_at  DATETIME     NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_qr_token_hash (token_hash),
    KEY idx_qr_session (session_id, expires_at),
    CONSTRAINT fk_qr_session FOREIGN KEY (session_id)
        REFERENCES attendance_sessions (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Only the DISTANCE and ACCURACY are kept, never the raw student
-- coordinates, so no location history is built up.
CREATE TABLE attendance_records (
    id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    session_id     INT UNSIGNED NOT NULL,
    student_id     INT UNSIGNED NOT NULL,
    marked_at      DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    distance_m     DECIMAL(8,2) NULL,
    gps_accuracy_m DECIMAL(8,2) NULL,
    device_id      INT UNSIGNED NULL,
    ip_address     VARCHAR(45)  NULL,
    PRIMARY KEY (id),
    -- Duplicate prevention lives in the database, not only in Python.
    UNIQUE KEY uq_attendance_session_student (session_id, student_id),
    KEY idx_attendance_student (student_id, marked_at),
    CONSTRAINT fk_att_session FOREIGN KEY (session_id)
        REFERENCES attendance_sessions (id) ON DELETE CASCADE,
    CONSTRAINT fk_att_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_att_device FOREIGN KEY (device_id)
        REFERENCES device_registrations (id) ON DELETE SET NULL,
    CONSTRAINT ck_att_distance CHECK (distance_m IS NULL OR distance_m >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE attendance_security_events (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    session_id  INT UNSIGNED NULL,
    student_id  INT UNSIGNED NULL,
    device_id   INT UNSIGNED NULL,
    event_type  ENUM('qr_invalid','qr_expired','session_closed','not_enrolled',
                     'duplicate','location_denied','location_missing',
                     'location_inaccurate','outside_radius','device_cooldown',
                     'rate_limited') NOT NULL,
    detail      VARCHAR(255) NULL,
    ip_address  VARCHAR(45)  NULL,
    created_at  DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_secevent_session (session_id, created_at),
    KEY idx_secevent_student (student_id, created_at),
    CONSTRAINT fk_secevent_session FOREIGN KEY (session_id)
        REFERENCES attendance_sessions (id) ON DELETE SET NULL,
    CONSTRAINT fk_secevent_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT fk_secevent_device FOREIGN KEY (device_id)
        REFERENCES device_registrations (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Persistent record used for login rate limiting (survives restarts).
CREATE TABLE login_attempts (
    id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    email        VARCHAR(190) NOT NULL,
    ip_address   VARCHAR(45)  NOT NULL,
    succeeded    TINYINT(1)   NOT NULL,
    attempted_at DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_login_email_time (email, attempted_at),
    KEY idx_login_ip_time (ip_address, attempted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 6. ACADEMIC RESULTS AND CONFIGURABLE GRADING
-- ---------------------------------------------------------------------

CREATE TABLE grading_schemes (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name        VARCHAR(80)  NOT NULL,
    description VARCHAR(255) NULL,
    is_default  TINYINT(1)   NOT NULL DEFAULT 0,
    created_at  DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_grading_scheme_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per grade band, e.g. 'A+' covers 90-100 and is worth 10 points.
CREATE TABLE grading_scheme_rules (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    scheme_id   INT UNSIGNED NOT NULL,
    grade_label VARCHAR(5)   NOT NULL,
    min_percent DECIMAL(5,2) NOT NULL,
    max_percent DECIMAL(5,2) NOT NULL,
    grade_point DECIMAL(4,2) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_rule_scheme_label (scheme_id, grade_label),
    CONSTRAINT fk_rule_scheme FOREIGN KEY (scheme_id)
        REFERENCES grading_schemes (id) ON DELETE CASCADE,
    CONSTRAINT ck_rule_range CHECK (
        min_percent >= 0 AND max_percent <= 100 AND min_percent <= max_percent),
    CONSTRAINT ck_rule_point CHECK (grade_point >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Grade, grade point and credits are SNAPSHOTTED when the result is
-- entered, so later scheme or credit edits do not rewrite history.
CREATE TABLE academic_results (
    id                INT UNSIGNED NOT NULL AUTO_INCREMENT,
    student_id        INT UNSIGNED NOT NULL,
    subject_id        INT UNSIGNED NOT NULL,
    semester_id       INT UNSIGNED NOT NULL,
    scheme_id         INT UNSIGNED NOT NULL,
    marks_obtained    DECIMAL(6,2) NOT NULL,
    max_marks         DECIMAL(6,2) NOT NULL DEFAULT 100,
    grade_label       VARCHAR(5)   NOT NULL,
    grade_point       DECIMAL(4,2) NOT NULL,
    credits_snapshot  DECIMAL(3,1) NOT NULL,
    is_published      TINYINT(1)   NOT NULL DEFAULT 0,
    entered_by        INT UNSIGNED NULL,
    entered_at        DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_result (student_id, subject_id, semester_id),
    KEY idx_result_student_sem (student_id, semester_id),
    CONSTRAINT fk_result_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_result_subject FOREIGN KEY (subject_id)
        REFERENCES subjects (id) ON DELETE RESTRICT,
    CONSTRAINT fk_result_semester FOREIGN KEY (semester_id)
        REFERENCES semesters (id) ON DELETE RESTRICT,
    CONSTRAINT fk_result_scheme FOREIGN KEY (scheme_id)
        REFERENCES grading_schemes (id) ON DELETE RESTRICT,
    CONSTRAINT fk_result_entered_by FOREIGN KEY (entered_by)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_result_marks CHECK (
        marks_obtained >= 0 AND max_marks > 0 AND marks_obtained <= max_marks)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 7. SYLLABUS AND LEARNING MATERIALS
-- ---------------------------------------------------------------------

CREATE TABLE syllabus (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
    subject_id  INT UNSIGNED NOT NULL,
    unit_number TINYINT UNSIGNED NOT NULL,
    title       VARCHAR(150) NOT NULL,
    topics      TEXT         NOT NULL,
    lecture_hours TINYINT UNSIGNED NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_syllabus_unit (subject_id, unit_number),
    CONSTRAINT fk_syllabus_subject FOREIGN KEY (subject_id)
        REFERENCES subjects (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Files live outside the web root under a random stored name; the
-- original filename is kept only for display and download.
CREATE TABLE learning_materials (
    id                INT UNSIGNED NOT NULL AUTO_INCREMENT,
    subject_id        INT UNSIGNED NOT NULL,
    title             VARCHAR(150) NOT NULL,
    original_filename VARCHAR(255) NOT NULL,
    stored_filename   VARCHAR(48)  NOT NULL,       -- random uuid4 hex + '.pdf'
    size_bytes        INT UNSIGNED NOT NULL,
    sha256            CHAR(64)     NOT NULL,
    uploaded_by       INT UNSIGNED NULL,
    uploaded_at       DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    UNIQUE KEY uq_material_stored (stored_filename),
    KEY idx_material_subject (subject_id),
    CONSTRAINT fk_material_subject FOREIGN KEY (subject_id)
        REFERENCES subjects (id) ON DELETE CASCADE,
    CONSTRAINT fk_material_uploader FOREIGN KEY (uploaded_by)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 8. NOTICES
-- ---------------------------------------------------------------------

CREATE TABLE notices (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    title         VARCHAR(180) NOT NULL,
    body          TEXT         NOT NULL,
    category      ENUM('exam','holiday','event','timetable','assignment','general')
                  NOT NULL DEFAULT 'general',
    audience      ENUM('all','student','teacher') NOT NULL DEFAULT 'all',
    department_id INT UNSIGNED NULL,               -- NULL = every department
    deadline_at   DATETIME     NULL,               -- assignment / exam dates
    is_active     TINYINT(1)   NOT NULL DEFAULT 1,
    created_by    INT UNSIGNED NULL,
    created_at    DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_notices_feed (is_active, audience, created_at),
    CONSTRAINT fk_notice_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE SET NULL,
    CONSTRAINT fk_notice_author FOREIGN KEY (created_by)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 9. FEES (administrator-managed records; no payment gateway)
-- ---------------------------------------------------------------------

CREATE TABLE fee_structures (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name             VARCHAR(120) NOT NULL,        -- e.g. 'Tuition Sem 3'
    department_id    INT UNSIGNED NULL,
    academic_year_id INT UNSIGNED NOT NULL,
    total_amount     DECIMAL(10,2) NOT NULL,
    due_date         DATE         NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_fee_structure (name, academic_year_id, department_id),
    CONSTRAINT fk_feestruct_department FOREIGN KEY (department_id)
        REFERENCES departments (id) ON DELETE SET NULL,
    CONSTRAINT fk_feestruct_year FOREIGN KEY (academic_year_id)
        REFERENCES academic_years (id) ON DELETE RESTRICT,
    CONSTRAINT ck_feestruct_total CHECK (total_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- amount_paid is kept in step with fee_transactions inside one database
-- transaction (see services/fee_service.py in Phase 7).
CREATE TABLE student_fee_records (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    student_id       INT UNSIGNED NOT NULL,
    fee_structure_id INT UNSIGNED NOT NULL,
    amount_due       DECIMAL(10,2) NOT NULL,
    amount_paid      DECIMAL(10,2) NOT NULL DEFAULT 0,
    due_date         DATE         NOT NULL,
    status           ENUM('unpaid','partial','paid') NOT NULL DEFAULT 'unpaid',
    PRIMARY KEY (id),
    UNIQUE KEY uq_student_fee (student_id, fee_structure_id),
    KEY idx_fee_status_due (status, due_date),
    CONSTRAINT fk_sfr_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_sfr_structure FOREIGN KEY (fee_structure_id)
        REFERENCES fee_structures (id) ON DELETE RESTRICT,
    CONSTRAINT ck_sfr_amounts CHECK (
        amount_due >= 0 AND amount_paid >= 0 AND amount_paid <= amount_due)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE fee_transactions (
    id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
    fee_record_id  INT UNSIGNED NOT NULL,
    amount         DECIMAL(10,2) NOT NULL,
    method         ENUM('cash','bank_transfer','cheque','other') NOT NULL,
    reference_no   VARCHAR(60)  NULL,
    paid_on        DATE         NOT NULL,
    note           VARCHAR(255) NULL,
    recorded_by    INT UNSIGNED NULL,
    created_at     DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_fee_tx_record (fee_record_id, paid_on),
    CONSTRAINT fk_feetx_record FOREIGN KEY (fee_record_id)
        REFERENCES student_fee_records (id) ON DELETE RESTRICT,
    CONSTRAINT fk_feetx_recorder FOREIGN KEY (recorded_by)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_feetx_amount CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 10. LIBRARY
-- ---------------------------------------------------------------------

CREATE TABLE library_books (
    id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
    isbn             VARCHAR(20)  NULL,
    title            VARCHAR(200) NOT NULL,
    author           VARCHAR(150) NOT NULL,
    category         VARCHAR(80)  NOT NULL,
    shelf_location   VARCHAR(40)  NULL,
    total_copies     SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    available_copies SMALLINT UNSIGNED NOT NULL DEFAULT 1,
    PRIMARY KEY (id),
    UNIQUE KEY uq_book_isbn (isbn),
    KEY idx_book_category (category),
    FULLTEXT KEY ft_book_search (title, author),
    CONSTRAINT ck_book_copies CHECK (available_copies <= total_copies)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- A book is overdue when returned_on IS NULL and due_on < today (UTC).
CREATE TABLE library_issues (
    id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
    book_id      INT UNSIGNED NOT NULL,
    student_id   INT UNSIGNED NOT NULL,
    issued_on    DATE         NOT NULL,
    due_on       DATE         NOT NULL,
    returned_on  DATE         NULL,
    fine_amount  DECIMAL(8,2) NOT NULL DEFAULT 0,
    issued_by    INT UNSIGNED NULL,
    PRIMARY KEY (id),
    KEY idx_issue_student (student_id, returned_on),
    KEY idx_issue_due (returned_on, due_on),
    CONSTRAINT fk_issue_book FOREIGN KEY (book_id)
        REFERENCES library_books (id) ON DELETE RESTRICT,
    CONSTRAINT fk_issue_student FOREIGN KEY (student_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_issue_issuer FOREIGN KEY (issued_by)
        REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT ck_issue_dates CHECK (due_on >= issued_on),
    CONSTRAINT ck_issue_fine CHECK (fine_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ---------------------------------------------------------------------
-- 11. AUDIT LOG
-- ---------------------------------------------------------------------

CREATE TABLE audit_logs (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id     INT UNSIGNED NULL,
    action      VARCHAR(60)  NOT NULL,            -- e.g. 'login.success'
    entity_type VARCHAR(40)  NULL,
    entity_id   VARCHAR(40)  NULL,
    details     JSON         NULL,
    ip_address  VARCHAR(45)  NULL,
    created_at  DATETIME     NOT NULL DEFAULT (UTC_TIMESTAMP()),
    PRIMARY KEY (id),
    KEY idx_audit_user (user_id, created_at),
    KEY idx_audit_action (action, created_at),
    KEY idx_audit_entity (entity_type, entity_id),
    CONSTRAINT fk_audit_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
